//! Parity gate against the piq 0.8.0 BRISQUE oracle:
//! `tests/goldens_brisque.tsv` holds `(path, score)` rows regenerated by
//! `tests/golden_brisque.py`. Every golden must land within `JND/1000` of
//! [`brisque::JND`]; the worst absolute delta and the worst delta in JND
//! units are printed. Paths are relative to
//! `$ZENMETRICS_NR_GOLDEN_ROOT` (default `~/tmp`).

use brisque::{Brisque, JND};
use std::io::BufRead;
use za::zenpixels::{PixelDescriptor, PixelSlice};
use za::{ErrorKind, EvalOpts, Image, NoReferenceMetric};
use zenmetrics_abstractions as za;

fn golden_root() -> std::path::PathBuf {
    std::env::var_os("ZENMETRICS_NR_GOLDEN_ROOT")
        .map(std::path::PathBuf::from)
        .unwrap_or_else(|| std::path::PathBuf::from(std::env::var("HOME").unwrap()).join("tmp"))
}

fn score_path(path: &std::path::Path) -> (u32, u32, Result<f64, ErrorKind>) {
    let path = &path.display().to_string();
    let img = image::open(path)
        .unwrap_or_else(|e| panic!("decode {path}: {e}"))
        .to_rgb8();
    let (w, h) = img.dimensions();
    let slice = PixelSlice::new(&img, w, h, w as usize * 3, PixelDescriptor::RGB8_SRGB).unwrap();
    let r = match Brisque::new().evaluate_image(Image::from(slice), EvalOpts::new()) {
        Ok(eval) => Ok(eval.score()),
        Err(e) => Err(e.error().kind()),
    };
    (w, h, r)
}

#[test]
fn matches_piq_goldens() {
    let tsv = std::fs::File::open(concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/tests/goldens_brisque.tsv"
    ))
    .expect("goldens_brisque.tsv (regenerate with tests/golden_brisque.py)");
    let root = golden_root();
    let tol = JND * 1e-3;
    let mut n = 0usize;
    let mut n_exact = 0usize;
    let mut worst_abs = 0.0f64;
    for line in std::io::BufReader::new(tsv).lines() {
        let line = line.unwrap();
        if line.starts_with('#') || line.is_empty() {
            continue;
        }
        let (path, expected) = line.split_once('\t').unwrap();
        let expected: f64 = expected.parse().unwrap();
        n += 1;
        let (w, h, got) = score_path(&root.join(path));
        if expected.is_nan() {
            let kind = if w.min(h) < 8 {
                ErrorKind::TooSmall
            } else {
                ErrorKind::Degenerate
            };
            assert_eq!(got, Err(kind), "{path}: oracle rejected input");
            continue;
        }
        assert!(expected.is_finite(), "{path}: infinite oracle row");
        let got = got.unwrap_or_else(|e| panic!("brisque {path}: {e:?}"));
        let d = (got - expected).abs();
        if d == 0.0 {
            n_exact += 1;
        }
        assert!(
            d <= tol,
            "{path}: expected {expected}, got {got} (|Δ|={d} > {tol} = JND/1000)"
        );
        worst_abs = worst_abs.max(d);
    }
    assert_eq!(n, 42 + 128, "goldens row count changed — regenerate");
    eprintln!(
        "brisque parity: {n} goldens ({n_exact} bitwise-exact), worst |Δ| = {worst_abs:.3e} absolute = {:.3e} JND",
        worst_abs / JND
    );
}
